+  "toSorted", "toReversed", "toSpliced",
+]);
+const preservesLength = new Set(["map", "toSorted", "toReversed"]);
+
+function unwrap(node) {
+  while (node && [
+    "ChainExpression", "TSAsExpression", "TSTypeAssertion",
+    "TSNonNullExpression", "TSSatisfiesExpression",
+  ].includes(node.type)) node = node.expression;
+  return node;
+}
+
+function method(node) {
+  const callee = unwrap(node?.callee);
+  if (callee?.type !== "MemberExpression") return null;
+  const name = callee.computed
+    ? callee.property.type === "Literal" && callee.property.value
+    : callee.property.name;
+  return { name, receiver: unwrap(callee.object) };
+}
